INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9210, 'ក្នុងចតុកោណកែង អង្កត់ទ្រូងទាំងពីរមានលក្ខណៈ ៖', NULL, '["\\(\\text{មានប្រវែងប៉ុនគ្នា}\\)", "\\(\\text{មានប្រវែងខុសគ្នាជានិច្ច}\\)", "\\(\\text{កែងគ្នាជានិច្ច}\\)", "\\(\\text{មិនកាត់គ្នា}\\)"]', 0, NULL, 1, 'mcq', 'អង្កត់ទ្រូងទាំងពីរនៃចតុកោណកែងមានប្រវែងប៉ុនគ្នា។', 'ចតុកោណ', 'easy', 1, '8', 'ចតុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9211, 'ក្នុងចតុកោណ \(ABCD\) មាន \(\angle A = 80^\circ, \angle B = 110^\circ, \angle C = 75^\circ\)។ រង្វាស់មុំ \(\angle D\) ស្មើ ៖', NULL, '["\\(105^\\circ\\)", "\\(95^\\circ\\)", "\\(85^\\circ\\)", "\\(90^\\circ\\)"]', 1, NULL, 2, 'mcq', '\(\angle D = 360^\circ - (80^\circ + 110^\circ + 75^\circ) = 360^\circ - 265^\circ = 95^\circ\)។', 'ចតុកោណ', 'medium', 1, '8', 'ចតុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9212, 'ក្នុងប្រលេឡូក្រាម \(ABCD\) មានមុំ \(\angle A = 70^\circ\)។ រង្វាស់មុំ \(\angle B\) ស្មើ ៖', NULL, '["\\(70^\\circ\\)", "\\(110^\\circ\\)", "\\(120^\\circ\\)", "\\(90^\\circ\\)"]', 1, NULL, 2, 'mcq', 'មុំតគ្នាក្នុងប្រលេឡូក្រាមជាមុំជាប់បន្ថែម ៖ \(\angle B = 180^\circ - 70^\circ = 110^\circ\)។', 'ចតុកោណ', 'medium', 1, '8', 'ចតុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9213, 'ចតុកោណព្នាយសមបាត \(ABCD\) (\(AB \parallel CD\)) មានមុំបាត \(\angle D = 65^\circ\)។ រង្វាស់មុំ \(\angle A\) ស្មើ ៖', NULL, '["\\(90^\\circ\\)", "\\(125^\\circ\\)", "\\(65^\\circ\\)", "\\(115^\\circ\\)"]', 3, NULL, 2, 'mcq', '\(\angle A = 180^\circ - 65^\circ = 115^\circ\) (មុំក្នុងរួមខាងព្រោះ \(AB \parallel CD\))។', 'ចតុកោណ', 'medium', 1, '8', 'ចតុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9214, 'ចតុកោណស្មើមួយមានបរិមាត្រ \(48\ \text{cm}\)។ ប្រវែងជ្រុងនីមួយៗរបស់វាស្មើ ៖', NULL, '["\\(8\\ \\text{cm}\\)", "\\(24\\ \\text{cm}\\)", "\\(16\\ \\text{cm}\\)", "\\(12\\ \\text{cm}\\)"]', 3, NULL, 2, 'mcq', '\(\dfrac{48}{4} = 12\ \text{cm}\) (ជ្រុងទាំងបួនប៉ុនគ្នា)។', 'ចតុកោណ', 'medium', 1, '8', 'ចតុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9215, 'ចតុកោណកែងមួយមានបណ្តោយ \(12\ \text{cm}\) និងទទឹង \(5\ \text{cm}\)។ ប្រវែងអង្កត់ទ្រូងរបស់វាស្មើ ៖', NULL, '["\\(10\\ \\text{cm}\\)", "\\(13\\ \\text{cm}\\)", "\\(17\\ \\text{cm}\\)", "\\(15\\ \\text{cm}\\)"]', 1, NULL, 2, 'mcq', '\(d = \sqrt{12^2 + 5^2} = \sqrt{144 + 25} = \sqrt{169} = 13\ \text{cm}\)។', 'ចតុកោណ', 'medium', 1, '8', 'ចតុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9216, 'ការេមួយមានប្រវែងអង្កត់ទ្រូង \(6\sqrt{2}\ \text{cm}\)។ ប្រវែងជ្រុងនៃការេនោះស្មើ ៖', NULL, '["\\(6\\sqrt{2}\\ \\text{cm}\\)", "\\(12\\ \\text{cm}\\)", "\\(3\\ \\text{cm}\\)", "\\(6\\ \\text{cm}\\)"]', 3, NULL, 2, 'mcq', 'អង្កត់ទ្រូងការេ \(d = a\sqrt{2} \Rightarrow a = 6\ \text{cm}\)។', 'ចតុកោណ', 'medium', 1, '8', 'ចតុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9217, 'ចតុកោណព្នាយមួយមានបាតតូច \(8\ \text{cm}\) និងបាតធំ \(14\ \text{cm}\)។ ប្រវែងមូលដ្ឋានមធ្យម (កាត់ចំណុចកណ្តាលជ្រុងទ្រេតទាំងពីរ) ស្មើ ៖', NULL, '["\\(12\\ \\text{cm}\\)", "\\(11\\ \\text{cm}\\)", "\\(22\\ \\text{cm}\\)", "\\(10\\ \\text{cm}\\)"]', 1, NULL, 2, 'mcq', '\(m = \dfrac{8 + 14}{2} = \dfrac{22}{2} = 11\ \text{cm}\)។', 'ចតុកោណ', 'medium', 1, '8', 'ចតុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9218, 'ក្នុងប្រលេឡូក្រាមមួយ មុំតគ្នាពីរមានផលធៀប \(1 \colon 3\)។ រង្វាស់មុំតូចគឺ ៖', NULL, '["\\(45^\\circ\\)", "\\(40^\\circ\\)", "\\(60^\\circ\\)", "\\(30^\\circ\\)"]', 0, NULL, 2, 'mcq', '\(x + 3x = 180^\circ \Rightarrow 4x = 180^\circ \Rightarrow x = 45^\circ\)។', 'ចតុកោណ', 'medium', 1, '8', 'ចតុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9219, 'ប្រលេឡូក្រាមមួយមានបរិមាត្រ \(36\ \text{cm}\) ហើយជ្រុងមួយវែងជាងជ្រុងមួយទៀត \(4\ \text{cm}\)។ ប្រវែងជ្រុងទាំងពីរគឺ ៖', NULL, '["\\(7\\ \\text{cm}\\ \\text{និង}\\ 11\\ \\text{cm}\\)", "\\(6\\ \\text{cm}\\ \\text{និង}\\ 10\\ \\text{cm}\\)", "\\(8\\ \\text{cm}\\ \\text{និង}\\ 12\\ \\text{cm}\\)", "\\(5\\ \\text{cm}\\ \\text{និង}\\ 9\\ \\text{cm}\\)"]', 0, NULL, 2, 'mcq', '\(2(x + x + 4) = 36 \Rightarrow 4x + 8 = 36 \Rightarrow 4x = 28 \Rightarrow x = 7\ \text{cm}\) នាំឱ្យជ្រុងគឺ 7 និង 11។', 'ចតុកោណ', 'medium', 1, '8', 'ចតុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9220, 'ចតុកោណខ្លែង \(ABCD\) មាន \(AB = AD\) និង \(CB = CD\)។ បើ \(\angle B = 100^\circ\) នោះរង្វាស់មុំ \(\angle D\) ស្មើ ៖', NULL, '["\\(90^\\circ\\)", "\\(120^\\circ\\)", "\\(100^\\circ\\)", "\\(80^\\circ\\)"]', 2, NULL, 2, 'mcq', 'ក្នុងចតុកោណខ្លែង មុំរវាងជ្រុងមិនស្មើគ្នាទាំងពីរគូជាមុំប៉ុនគ្នា ៖ \(\angle B = \angle D = 100^\circ\)។', 'ចតុកោណ', 'medium', 1, '8', 'ចតុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9221, 'ប្រលេឡូក្រាមដែលមានអង្កត់ទ្រូងទាំងពីរប៉ុនគ្នាផង និងកែងគ្នាផង គឺជា ៖', NULL, '["\\(\\text{ការេ}\\)", "\\(\\text{ចតុកោណកែង}\\)", "\\(\\text{ចតុកោណព្នាយ}\\)", "\\(\\text{ចតុកោណស្មើ}\\)"]', 0, NULL, 2, 'mcq', 'អង្កត់ទ្រូងប៉ុនគ្នា (ចតុកោណកែង) + កែងគ្នា (ចតុកោណស្មើ) $\implies$ ការេ (Square)។', 'ចតុកោណ', 'medium', 1, '8', 'ចតុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9222, 'ក្នុងប្រលេឡូក្រាម \(ABCD\) មានមុំឈម \(\angle A = 2x + 10^\circ\) និង \(\angle C = 3x - 20^\circ\)។ តម្លៃនៃ \(x\) គឺ ៖', NULL, '["\\(20^\\circ\\)", "\\(30^\\circ\\)", "\\(25^\\circ\\)", "\\(40^\\circ\\)"]', 1, NULL, 2, 'mcq', '\(2x + 10 = 3x - 20 \Rightarrow x = 30^\circ\) នាំឱ្យ \(\angle A = \angle C = 70^\circ\)។', 'ចតុកោណ', 'medium', 1, '8', 'ចតុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9223, 'ចតុកោណស្មើមួយមានជ្រុងប្រវែង \(5\ \text{cm}\) និងអង្កត់ទ្រូងមួយប្រវែង \(6\ \text{cm}\)។ ប្រវែងអង្កត់ទ្រូងមួយទៀតស្មើ ៖', NULL, '["\\(6\\ \\text{cm}\\)", "\\(4\\ \\text{cm}\\)", "\\(8\\ \\text{cm}\\)", "\\(10\\ \\text{cm}\\)"]', 2, NULL, 2, 'mcq', 'ពាក់កណ្តាលអង្កត់ទ្រូង \(\sqrt{5^2 - 3^2} = 4\ \text{cm}\) នាំឱ្យអង្កត់ទ្រូងទីពីរគឺ \(2 \times 4 = 8\ \text{cm}\)។', 'ចតុកោណ', 'medium', 1, '8', 'ចតុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9224, 'ប្រលេឡូក្រាម \(ABCD\) មានអង្កត់ទ្រូងកាត់គ្នាត្រង់ \(O\)។ បើ \(OA = 3x - 5\) និង \(OC = x + 7\) នោះ \(x\) ស្មើ ៖', NULL, '["\\(4\\)", "\\(6\\)", "\\(5\\)", "\\(8\\)"]', 1, NULL, 2, 'mcq', '\(3x - 5 = x + 7 \Rightarrow 2x = 12 \Rightarrow x = 6\) នាំឱ្យ \(OA = OC = 13\)។', 'ចតុកោណ', 'medium', 1, '8', 'ចតុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9225, 'ក្នុងប្រលេឡូក្រាម \(ABCD\) មាន \(\angle A = 5x - 20^\circ\) និង \(\angle B = 3x + 40^\circ\)។ រង្វាស់មុំ \(\angle A\) ស្មើ ៖', NULL, '["\\(80^\\circ\\)", "\\(85^\\circ\\)", "\\(75^\\circ\\)", "\\(100^\\circ\\)"]', 0, NULL, 3, 'mcq', '\((5x - 20) + (3x + 40) = 180 \Rightarrow 8x = 160 \Rightarrow x = 20^\circ\) នាំឱ្យ \(\angle A = 5(20) - 20 = 80^\circ\)។', 'ចតុកោណ', 'hard', 1, '8', 'ចតុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9226, 'ចតុកោណស្មើ \(ABCD\) មានអង្កត់ទ្រូង \(AC\) ស្មើនឹងជ្រុង \(AB\)។ រង្វាស់មុំទាល \(\angle B\) ស្មើ ៖', NULL, '["\\(135^\\circ\\)", "\\(120^\\circ\\)", "\\(100^\\circ\\)", "\\(110^\\circ\\)"]', 1, NULL, 3, 'mcq', '\(\Delta ABC\) សម័ង្ស នាំឱ្យ \(\angle BAC = 60^\circ\) នាំឱ្យ \(\angle A = 120^\circ\) ឬ \(\angle B = 180^\circ - 60^\circ = 120^\circ\)។', 'ចតុកោណ', 'hard', 1, '8', 'ចតុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9227, 'ការេមួយមានផ្ទៃក្រឡា \(100\ \text{cm}^2\)។ ប្រវែងអង្កត់ទ្រូងរបស់វាគឺ ៖', NULL, '["\\(14\\ \\text{cm}\\)", "\\(10\\sqrt{2}\\ \\text{cm}\\)", "\\(20\\ \\text{cm}\\)", "\\(10\\ \\text{cm}\\)"]', 1, NULL, 3, 'mcq', '\(a = 10\ \text{cm} \Rightarrow d = 10\sqrt{2}\ \text{cm}\)។', 'ចតុកោណ', 'hard', 1, '8', 'ចតុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9228, 'ក្នុងប្រលេឡូក្រាម \(ABCD\) កន្លះបន្ទាត់ពុះមុំ \(\angle A\) កាត់ជ្រុង \(BC\) ត្រង់ \(E\)។ ត្រីកោណ \(ABE\) ជា ៖', NULL, '["\\(\\text{ត្រីកោណសមបាតកំពូល } B\\)", "\\(\\text{ត្រីកោណកែង}\\)", "\\(\\text{ត្រីកោណសម័ង្ស}\\)", "\\(\\text{ត្រីកោណទូទៅ}\\)"]', 0, NULL, 3, 'mcq', '\(\angle BAE = \angle EAD = \angle BEA\) (មុំឆ្លាស់ក្នុង) នាំឱ្យ \(BA = BE\) (សមបាត)។', 'ចតុកោណ', 'hard', 1, '8', 'ចតុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9229, 'ចតុកោណព្នាយកែង \(ABCD\) មានមុំកែង \(\angle A = \angle D = 90^\circ\) បាត \(AB = 4\ \text{cm}\), \(CD = 9\ \text{cm}\) និងកម្ពស់ \(AD = 12\ \text{cm}\)។ ប្រវែងជ្រុងទ្រេត \(BC\) ស្មើ ៖', NULL, '["\\(11\\ \\text{cm}\\)", "\\(15\\ \\text{cm}\\)", "\\(12\\ \\text{cm}\\)", "\\(13\\ \\text{cm}\\)"]', 3, NULL, 3, 'mcq', '\(HC = 9 - 4 = 5\ \text{cm} \Rightarrow BC = \sqrt{12^2 + 5^2} = 13\ \text{cm}\)។', 'ចតុកោណ', 'hard', 1, '8', 'ចតុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9230, 'ចតុកោណខ្លែងមួយមានអង្កត់ទ្រូងទាំងពីរប្រវែង \(16\ \text{cm}\) និង \(25\ \text{cm}\)។ ផ្ទៃក្រឡារបស់វាស្មើ ៖', NULL, '["\\(400\\ \\text{cm}^2\\)", "\\(250\\ \\text{cm}^2\\)", "\\(100\\ \\text{cm}^2\\)", "\\(200\\ \\text{cm}^2\\)"]', 3, NULL, 3, 'mcq', '\(S = \dfrac{16 \times 25}{2} = 200\ \text{cm}^2\)។', 'ចតុកោណ', 'hard', 1, '8', 'ចតុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9231, 'ផ្ចិតឆ្លុះនៃប្រលេឡូក្រាមមួយគឺជា ៖', NULL, '["\\(\\text{កំពូលណាមួយ}\\)", "\\(\\text{គ្មានផ្ចិតឆ្លុះទេ}\\)", "\\(\\text{ចំណុចកណ្តាលនៃជ្រុងមួយ}\\)", "\\(\\text{ចំណុចប្រសព្វនៃអង្កត់ទ្រូងទាំងពីរ}\\)"]', 3, NULL, 3, 'mcq', 'ចំណុចប្រសព្វនៃអង្កត់ទ្រូងជាផ្ចិតឆ្លុះនៃប្រលេឡូក្រាម។', 'ចតុកោណ', 'hard', 1, '8', 'ចតុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9232, 'ទ្វាររបងឈើរាងចតុកោណកែងមានទទឹង \(1.5\ \text{m}\) និងកម្ពស់ \(2\ \text{m}\) (ដូចរូប)។ ប្រវែងបន្ទះក្តារបន្ទូលខ្វែងអង្កត់ទ្រូង (\(d\)) ដើម្បីទប់ទ្វារកុំឱ្យទ្រេតគឺ ៖', 'g8-49845401c9.svg', '["\\(2.5\\ \\text{m}\\)", "\\(3\\ \\text{m}\\)", "\\(2.2\\ \\text{m}\\)", "\\(3.5\\ \\text{m}\\)"]', 0, NULL, 3, 'mcq', '\(d = \sqrt{1.5^2 + 2^2} = \sqrt{2.25 + 4} = \sqrt{6.25} = 2.5\ \text{m}\)។', 'ចតុកោណ', 'pisa', 1, '8', 'ចតុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9233, 'ដីស្រែរាងចតុកោណព្នាយមានបាតតូច \(30\ \text{m}\), បាតធំ \(50\ \text{m}\) និងកម្ពស់ \(20\ \text{m}\)។ ផ្ទៃក្រឡាដីស្រែនោះគឺ ៖', NULL, '["\\(800\\ \\text{m}^2\\)", "\\(600\\ \\text{m}^2\\)", "\\(1\\,600\\ \\text{m}^2\\)", "\\(750\\ \\text{m}^2\\)"]', 0, NULL, 3, 'mcq', '\(S = \dfrac{(30 + 50) \times 20}{2} = 800\ \text{m}^2\)។', 'ចតុកោណ', 'pisa', 1, '8', 'ចតុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9234, 'កុមារាម្នាក់ធ្វើខ្លែងរាងចតុកោណខ្លែងដោយប្រើឆ្អឹងខ្នងខ្វែងគ្នាកែងប្រវែង \(40\ \text{cm}\) និង \(30\ \text{cm}\)។ ផ្ទៃក្រឡាខ្លែងនោះគឺ ៖', NULL, '["\\(700\\ \\text{cm}^2\\)", "\\(300\\ \\text{cm}^2\\)", "\\(1\\,200\\ \\text{cm}^2\\)", "\\(600\\ \\text{cm}^2\\)"]', 3, NULL, 3, 'mcq', '\(S = \dfrac{40 \times 30}{2} = 600\ \text{cm}^2\)។', 'ចតុកោណ', 'pisa', 1, '8', 'ចតុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9235, 'ការ៉ូផ្កាថ្មរាងចតុកោណស្មើមានអង្កត់ទ្រូង \(24\ \text{cm}\) និង \(10\ \text{cm}\)។ ផ្ទៃក្រឡានៃការ៉ូមួយដុំគឺ ៖', NULL, '["\\(120\\ \\text{cm}^2\\)", "\\(150\\ \\text{cm}^2\\)", "\\(60\\ \\text{cm}^2\\)", "\\(240\\ \\text{cm}^2\\)"]', 0, NULL, 3, 'mcq', '\(S = \dfrac{24 \times 10}{2} = 120\ \text{cm}^2\)។', 'ចតុកោណ', 'pisa', 1, '8', 'ចតុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9236, 'ប្រឡោះចតរថយន្តរាងប្រលេឡូក្រាមមានបាត \(2.5\ \text{m}\) និងកម្ពស់កែង \(5\ \text{m}\)។ ផ្ទៃក្រឡានៃប្រឡោះចតរថយន្តមួយគឺ ៖', NULL, '["\\(15\\ \\text{m}^2\\)", "\\(25\\ \\text{m}^2\\)", "\\(10\\ \\text{m}^2\\)", "\\(12.5\\ \\text{m}^2\\)"]', 3, NULL, 3, 'mcq', '\(S = 2.5 \times 5 = 12.5\ \text{m}^2\)។', 'ចតុកោណ', 'pisa', 1, '8', 'ចតុកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9237, 'ក្នុងចតុកោណ \(ABCD\) មួយមាន \(\angle A = 85^\circ, \angle B = 115^\circ, \angle C = 70^\circ\)។ ក. រំលឹកផលបូករង្វាស់មុំក្នុងទាំងបួននៃចតុកោណមួយ។ ខ. សរសេរសមីការគណនាមុំ \(\angle D\)។ គ. គណនារង្វាស់មុំ \(\angle D\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ផលបូករង្វាស់មុំក្នុងទាំងបួននៃចតុកោណមួយស្មើនឹង \(360^\circ\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9238, 'ក្នុងប្រលេឡូក្រាម \(ABCD\) មួយមានមុំឈម \(\angle A = 2x + 10^\circ\) និង \(\angle C = 3x - 20^\circ\)។ ក. បញ្ជាក់ទំនាក់ទំនងរវាងមុំឈម \(\angle A\) និង \(\angle C\)។ ខ. រកតម្លៃនៃ \(x\)។ គ. គណនារង្វាស់មុំទាំងបួននៃប្រលេឡូក្រាម។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ក្នុងប្រលេឡូក្រាម មុំឈមជាមុំប៉ុនគ្នា នាំឱ្យ \(\angle A = \angle C\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9239, 'ប្រលេឡូក្រាម \(ABCD\) មានអង្កត់ទ្រូង \(AC\) និង \(BD\) ប្រសព្វគ្នាត្រង់ \(O\)។ គេដឹងថា \(OA = 3x - 5\ \text{cm}\) និង \(OC = x + 7\ \text{cm}\)។ ក. បញ្ជាក់លក្ខណៈប្រសព្វនៃអង្កត់ទ្រូងទាំងពីរ។ ខ. រកតម្លៃនៃ \(x\)។ គ. គណនាប្រវែងអង្កត់ទ្រូង \(AC\)។', 'g8-1de5c9b7aa.svg', '[]', 0, NULL, 5, 'writing', 'ក. អង្កត់ទ្រូងទាំងពីរកាត់គ្នាត្រង់ចំណុចកណ្តាល \(O\) នាំឱ្យ \(OA = OC\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9240, 'ចតុកោណព្នាយសមបាត \(ABCD\) (\(AB \parallel CD\)) មានមុំបាត \(\angle D = 65^\circ\)។ ក. គណនារង្វាស់មុំបាត \(\angle C\)។ ខ. គណនារង្វាស់មុំ \(\angle A\) និង \(\angle B\)។ គ. ពន្យល់ទំនាក់ទំនងរវាងអង្កត់ទ្រូង \(AC\) និង \(BD\)។', 'g8-8ee2ca6519.svg', '[]', 0, NULL, 5, 'writing', 'ក. ចតុកោណព្នាយសមបាតមានមុំបាតស្មើគ្នា នាំឱ្យ \(\angle C = \angle D = 65^\circ\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9241, 'ចតុកោណស្មើ \(ABCD\) មានជ្រុង \(AB = 5\ \text{cm}\) និងអង្កត់ទ្រូង \(BD = 6\ \text{cm}\) កាត់ \(AC\) ត្រង់ \(O\)។ ក. បញ្ជាក់រង្វាស់ជ្រុងទាំងបួន។ ខ. បញ្ជាក់លក្ខណៈកែងគ្នានៃអង្កត់ទ្រូងទាំងពីរ។ គ. គណនាប្រវែងអង្កត់ទ្រូង \(AC\)។', 'g8-b887e16cdf.svg', '[]', 0, NULL, 5, 'writing', 'ក. ជ្រុងទាំងបួនប៉ុនគ្នា ៖ \(AB = BC = CD = DA = 5\ \text{cm}\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9242, '\(\Delta ABC\) ជាត្រីកោណសមបាតកំពូល \(A\) (\(AB = AC\))។ \(M\) ជាចំណុចកណ្តាលនៃ \(BC\)។ តាម \(A\) គូសបន្ទាត់ស្របនឹង \(BC\) ហើយតាម \(C\) គូសបន្ទាត់ស្របនឹង \(AM\) បន្ទាត់ទាំងពីរជួបគ្នាត្រង់ \(D\)។ ក. បង្ហាញថាចតុកោណ \(AMCD\) ជាចតុកោណកែង។ ខ. បង្ហាញថា \(AD = MC = MB\)។ គ. បង្ហាញថាចតុកោណ \(ABMD\) ជាប្រលេឡូក្រាម។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(AD \parallel MC\) និង \(CD \parallel AM \Rightarrow AMCD\) ជាប្រលេឡូក្រាម។ ដោយ \(AM \perp BC \Rightarrow \angle AMC = 90^\circ\) នាំឱ្យ \(AMCD\) ជាចតុកោណកែង (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9243, 'ចតុកោណកែង \(ABCD\) មានអង្កត់ទ្រូង \(AC\) និង \(BD\) កាត់គ្នាត្រង់ \(O\)។ ក. ប្រើត្រីកោណប៉ុនគ្នា \(\Delta ABC\) និង \(\Delta BAD\) បង្ហាញថា \(AC = BD\)។ ខ. បង្ហាញថា \(O\) ជាចំណុចកណ្តាលនៃ \(AC\) និង \(BD\)។ គ. ទាញបញ្ជាក់ថា \(OA = OB = OC = OD\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ត្រីកោណកែង \(ABC\) និង \(BAD\) មាន \(AB\) ជាជ្រុងរួម, \(BC = AD\) នាំឱ្យ \(\Delta ABC \cong \Delta BAD\) (ជ.ម.ជ) នាំឱ្យ \(AC = BD\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9244, 'ក្នុងប្រលេឡូក្រាម \(ABCD\) មានមុំតគ្នា \(\angle A = 5x - 20^\circ\) និង \(\angle B = 3x + 40^\circ\)។ ក. សរសេរទំនាក់ទំនងផលបូក \(\angle A + \angle B\)។ ខ. រកតម្លៃនៃ \(x\)។ គ. គណនារង្វាស់មុំទាំងបួន។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. មុំតគ្នាក្នុងប្រលេឡូក្រាមជាមុំជាប់បន្ថែម ៖ \(\angle A + \angle B = 180^\circ\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9245, 'ចតុកោណ \(ABCD\) មាន \(AB = AD\) និង \(CB = CD\) (ចតុកោណខ្លែង)។ ក. បង្ហាញថាចំណុច \(A\) និង \(C\) ឋិតនៅលើមេដ្យាទ័រនៃ \(BD\)។ ខ. ទាញបញ្ជាក់ថា \(AC \perp BD\)។ គ. បង្ហាញថា \(AC\) ជាបន្ទាត់ពុះមុំ \(\angle A\) និង \(\angle C\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(AB = AD \Rightarrow A\) នៅលើមេដ្យាទ័រនៃ \(BD\); \(CB = CD \Rightarrow C\) នៅលើមេដ្យាទ័រនៃ \(BD\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9246, 'ទ្វាររបងឈើមួយមានរាងចតុកោណកែងទទឹង \(1.5\ \text{m}\) និងកម្ពស់ \(2\ \text{m}\)។ ក. ពន្យល់ហេតុអ្វីគេត្រូវវាយបន្ទះក្តារបន្ទូលខ្វែងអង្កត់ទ្រូង (Cross-brace)។ ខ. គណនាប្រវែងបន្ទះក្តារខ្វែងនោះ។ គ. បើគ្មានបន្ទះក្តារខ្វែង តើទ្វារអាចប្រែប្រួលរាងយ៉ាងដូចម្តេច?', 'g8-49845401c9.svg', '[]', 0, NULL, 5, 'writing', 'ក. បន្ទះក្តារខ្វែងបំបែកចតុកោណកែងទៅជាត្រីកោណពីរដែលមានរាងរឹងមាំមិនប្រែប្រួលរាង (Triangle Rigidity) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9247, 'ដីស្រែរាងចតុកោណព្នាយ \(ABCD\) (\(AB \parallel CD\)) មានបាតតូច \(AB = 30\ \text{m}\), បាតធំ \(CD = 50\ \text{m}\) និងកម្ពស់ \(20\ \text{m}\)។ ក. គណនាផ្ទៃក្រឡាដីស្រែសរុប។ ខ. គេចែកដីជាពីរចំណែក ៖ ត្រីកោណកែង \(ADH\) (\(DH = 10\ \text{m}\)) និងចតុកោណព្នាយកែង \(ABCH\) (\(HC = 40\ \text{m}\))។ គណនាផ្ទៃក្រឡាចំណែកនីមួយៗ។ គ. ផ្ទៀងផ្ទាត់ផលបូកផ្ទៃក្រឡាទាំងពីរ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ផ្ទៃសរុប ៖ \(S = \dfrac{(30 + 50) \times 20}{2} = 800\ \text{m}^2\) (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9248, 'កុមារាម្នាក់ធ្វើខ្លែងរាងចតុកោណខ្លែង \(ABCD\) ដោយប្រើបន្ទះឫស្សីខ្វែងគ្នាកែង \(AC = 40\ \text{cm}\) និង \(BD = 30\ \text{cm}\)។ ក. ពន្យល់លក្ខណៈកែងគ្នានៃឆ្អឹងខ្នងទាំងពីរ។ ខ. គណនាផ្ទៃក្រឡានៃខ្លែង។ គ. បើគាត់ចង់បិទក្រដាសបន្ថែមគែម \(10\%\) តើត្រូវត្រៀមក្រដាសផ្ទៃប៉ុន្មាន?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ឆ្អឹងខ្នងទាំងពីរកែងគ្នាព្រោះចតុកោណខ្លែងមានអង្កត់ទ្រូងកាត់គ្នាកែង (\(AC \perp BD\)) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9249, 'សាលប្រជុំមួយក្រាលការ៉ូរាងចតុកោណស្មើដែលមានអង្កត់ទ្រូង \(24\ \text{cm}\) និង \(10\ \text{cm}\)។ ក. គណនាផ្ទៃក្រឡានៃការ៉ូមួយដុំ។ ខ. គណនាប្រវែងជ្រុងនៃការ៉ូនីមួយៗ។ គ. បើសាលប្រជុំមានផ្ទៃ \(60\ \text{m}^2\) (\(600\,000\ \text{cm}^2\)) តើត្រូវការ៉ូប៉ុន្មានដុំ?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ផ្ទៃក្រឡាការ៉ូមួយដុំ ៖ \(S_1 = \dfrac{24 \times 10}{2} = 120\ \text{cm}^2\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9250, 'ចំណតរថយន្តមានប្រឡោះរាងប្រលេឡូក្រាមមានបាត \(b = 2.5\ \text{m}\), កម្ពស់កែង \(h = 5\ \text{m}\) និងជ្រុងទ្រេត \(6\ \text{m}\)។ ក. គណនាផ្ទៃក្រឡានៃប្រឡោះមួយ។ ខ. បើមាន ២០ ប្រឡោះ គណនាផ្ទៃក្រឡាសរុប។ គ. ហេតុអ្វីបានជាគេរចនាប្រឡោះចតជារាងប្រលេឡូក្រាមទ្រេត?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ផ្ទៃក្រឡាមួយប្រឡោះ ៖ \(S = b \times h = 2.5 \times 5 = 12.5\ \text{m}^2\) (2 ពិន្ទុ)
